define(['core/log','core/notification','core/str'],function(a,b,c){return{init:function(){document.querySelectorAll('.videotrack-delete-preset-form').forEach(function(form){form.addEventListener('submit',function(e){if(form.dataset.confirmed==='1'){return;}e.preventDefault();var d=form.querySelector('[data-confirm]');var e=(d&&d.getAttribute('data-confirm'))||'Delete this preset?';c.get_strings([{key:'confirm',component:'moodle'},{key:'delete',component:'moodle'},{key:'cancel',component:'moodle'}]).then(function(strings){return b.confirm(strings[0],e,strings[1],strings[2],function(){form.dataset.confirmed='1';form.submit();});}).catch(function(){return b.confirm('Confirm',e,'Delete','Cancel',function(){form.dataset.confirmed='1';form.submit();});});});});a.debug('mod_videotrack/presets: initialised');}};});